const classes = [
    ...game.items.contents.filter((i) => i.type === "class"),
    ...(
        await Promise.all(
            game.packs.contents
                .filter((p) => p.metadata.type === "Item")
                .map((p) => p.getDocuments({ type: "class" })),
        )
    ).flat(),
].filter((c) => !c.getFlag("pf2e-dual-class", "sourceClasses"));

const module = game.modules.get("pf2e-dual-class");
const picked = await module.api.promptForTwoClasses(classes);
if (picked) await module.api.createDualClassItem(picked.class1, picked.class2);
